<script setup lang="ts">
import { ArrowLeft, ArrowRight, CheckCircle2, Eye, EyeOff } from '@lucide/vue'; import { reactive, ref } from 'vue'; import { useRouter } from 'vue-router'; import { useAuthStore } from '../stores/auth'; import BrandLogo from '../components/BrandLogo.vue'
const form=reactive({name:'',email:'',academy_name:'',phone:'',password:'',password_confirmation:''});const visible=ref(false);const loading=ref(false);const error=ref('');const auth=useAuthStore();const router=useRouter()
async function submit(){loading.value=true;error.value='';try{await auth.register(form);router.replace('/verify-email')}catch(e:any){const errors=e.response?.data?.errors;error.value=errors?Object.values(errors).flat().join(' '):(e.response?.data?.message||'We could not create your workspace.')}finally{loading.value=false}}
</script>
<template><main class="auth-layout register"><section class="auth-story"><BrandLogo light/><div class="story-copy"><span class="eyebrow light">14 DAYS · NO CARD REQUIRED</span><h1>Give your academy<br><em>room to grow.</em></h1><p>Start with a secure private workspace. We’ll guide you through the rest.</p><ul><li><CheckCircle2/>Egyptian academic defaults included</li><li><CheckCircle2/>Ready for Arabic and English</li><li><CheckCircle2/>Your data stays isolated</li></ul></div><footer>ACADEMYHUB <span>BUILT FOR REAL TEACHING DAYS</span></footer></section><section class="auth-panel"><div class="auth-box register-box"><RouterLink to="/" class="back-link"><ArrowLeft/> Back to home</RouterLink><span class="eyebrow">CREATE YOUR WORKSPACE</span><h2>Let’s build your academy.</h2><p>You can adjust these details later in settings.</p><form class="register-form" @submit.prevent="submit"><label>Your full name<input v-model="form.name" required placeholder="Mariam Beshoy"></label><label>Work email<input v-model="form.email" type="email" required placeholder="mariam@academy.com"></label><label class="full">Academy or centre name<input v-model="form.academy_name" required placeholder="Future Leaders Academy"></label><label class="full">Mobile / WhatsApp number<input v-model="form.phone" required placeholder="+20 10 0000 0000"></label><label>Password<div class="password-field"><input v-model="form.password" :type="visible?'text':'password'" required placeholder="8+ letters and numbers"><button type="button" @click="visible=!visible"><EyeOff v-if="visible"/><Eye v-else/></button></div></label><label>Confirm password<input v-model="form.password_confirmation" type="password" required placeholder="Repeat password"></label><div v-if="error" class="form-error full">{{ error }}</div><button class="button primary wide full" :disabled="loading">{{loading?'Creating your workspace…':'Create my workspace'}} <ArrowRight/></button></form><small class="fine-print">By creating a workspace, you agree to the Terms and Privacy Policy.</small><p class="auth-switch">Already have a workspace? <RouterLink to="/login">Sign in</RouterLink></p></div></section></main></template>
